DWORD GetOSFileVersion(void) {
/*
Contains version information for a file. Src: https://learn.microsoft.com/en-us/windows/win32/api/verrsrc/ns-verrsrc-vs_fixedfileinfo
typedef struct tagVS_FIXEDFILEINFO {
  DWORD dwSignature;
  DWORD dwStrucVersion;
  DWORD dwFileVersionMS;
  DWORD dwFileVersionLS;
  DWORD dwProductVersionMS;
  DWORD dwProductVersionLS;
  DWORD dwFileFlagsMask;
  DWORD dwFileFlags;
  DWORD dwFileOS;
  DWORD dwFileType;
  DWORD dwFileSubtype;
  DWORD dwFileDateMS;
  DWORD dwFileDateLS;
} VS_FIXEDFILEINFO;
*/
	
	char NtosFile[] = "c:\\windows\\system32\\ntoskrnl.exe";
	LPVOID lpBuffer = NULL;
	UINT uLen = 0;
	DWORD ret = 0;
	
	// get size of file version data
	DWORD VerInfoSize = GetFileVersionInfoSizeA(NtosFile, NULL);
	if (VerInfoSize != 0 ) {
		LPVOID VerInfoData = malloc(VerInfoSize);
	
		// extract it and "convert" into VS_FIXEDFILEINFO structure
		if (GetFileVersionInfoA(NtosFile, 0, VerInfoSize, VerInfoData)) {
			VerQueryValueA(VerInfoData, "\\", &lpBuffer, &uLen);
			if (lpBuffer != NULL && uLen != 0) {
				VS_FIXEDFILEINFO * VerInfo = (VS_FIXEDFILEINFO *) lpBuffer;
				
				// found our OS file version minor number
				ret = (VerInfo->dwFileVersionLS) & 0xffff;
			}
		}
		free(VerInfoData);
	}
	
	return ret;
}

int AESDecrypt(char * payload, unsigned int payload_len, char * key, size_t keylen) {
	HCRYPTPROV hProv;
	HCRYPTHASH hHash;
	HCRYPTKEY hKey;

	if (!CryptAcquireContextA(&hProv, NULL, NULL, PROV_RSA_AES, CRYPT_VERIFYCONTEXT)){
			return -1;
	}
	if (!CryptCreateHash(hProv, CALG_SHA_256, 0, 0, &hHash)){
			return -1;
	}
	if (!CryptHashData(hHash, (BYTE*) key, (DWORD) keylen, 0)){
			return -1;              
	}
	if (!CryptDeriveKey(hProv, CALG_AES_256, hHash, 0,&hKey)){
			return -1;
	}
	
	if (!CryptDecrypt(hKey, (HCRYPTHASH) NULL, 0, 0, (BYTE *) payload, (DWORD *) &payload_len)){
			return -1;
	}
	
	CryptReleaseContext(hProv, 0);
	CryptDestroyHash(hHash);
	CryptDestroyKey(hKey);
	
	return 0;
}


