BOOL SetPrivilege(LPCTSTR Privilege, BOOL Enable) {
	BOOL ret = FALSE;
    HANDLE Token;
    TOKEN_PRIVILEGES tp;
    LUID luid;

	if (!OpenProcessToken((HANDLE)GetCurrentProcess(), TOKEN_ADJUST_PRIVILEGES, &Token)) {
		PRINT("OpenProcessToken() failed!\n");
		return ret;
	}

    if (!LookupPrivilegeValueA( 
		NULL,			// lookup privilege on local system
		Privilege,		// privilege to lookup 
		&luid ))		// receives LUID of privilege
    {
        PRINT("LookupPrivilegeValue error: %u\n", GetLastError() ); 
		goto cleanup;
    }

    tp.PrivilegeCount = 1;
    tp.Privileges[0].Luid = luid;
    //if (Enable)
    tp.Privileges[0].Attributes = Enable ? SE_PRIVILEGE_ENABLED : 0;
    //else
    //  tp.Privileges[0].Attributes = 0;

    if (!ADVAPI32$AdjustTokenPrivileges(Token, FALSE, &tp, sizeof(TOKEN_PRIVILEGES), (PTOKEN_PRIVILEGES) NULL, (PDWORD) NULL) ) { 
		PRINT("[!] AdjustTokenPrivileges error: %u\n", GetLastError() );
		goto cleanup;
    } 

    if (GetLastError() == ERROR_NOT_ALL_ASSIGNED) {
		PRINT("[!] The token does not have the specified privilege.\n");
		goto cleanup;
    }
	ret = TRUE;
	
cleanup:
	CloseHandle(Token);
	return ret;
}


BOOL LoadUnloadDriver(BOOL Load,WCHAR *ServiceName) {
	BOOL ret = TRUE;
	WCHAR RegPath[MAX_PATH] = L"\\Registry\\Machine\\System\\CurrentControlSet\\Services\\";
	wcscat(RegPath, ServiceName);
	
	// Enable driver loading privileges
	if (!SetPrivilege("SeLoadDriverPrivilege", PRIV_ENABLE)) {
		PRINT("[!] Boooo! No powers, we die!\n");
		return FALSE;
	}

	PRINT("\n[+] %s driver [%ls]...\n", Load ? "Loading" : "Unloading", RegPath);
	UNICODE_STRING* DrvServiceName;
	NTSTATUS status;
	
	// load or unload the driver, depending on the given option
	RtlInitUnicodeString_t pRtlInitUnicodeString = NULL;
	pRtlInitUnicodeString = (RtlInitUnicodeString_t)GetProcAddress(GetModuleHandleA("ntdll.dll"), "RtlInitUnicodeString");
	pRtlInitUnicodeString(DrvServiceName, RegPath);
	
	if (Load) {
		NtLoadDriver_t pNtLoadDriver = NULL;
		pNtLoadDriver = (NtLoadDriver_t)GetProcAddress(GetModuleHandleA("ntdll.dll"), "NtLoadDriver");
		status = pNtLoadDriver(DrvServiceName);
	} else {
		NtUnLoadDriver_t pNtUnLoadDriver = NULL;
		pNtUnLoadDriver = (NtUnLoadDriver_t)GetProcAddress(GetModuleHandleA("ntdll.dll"), "NtUnloadDriver");
		status = pNtUnLoadDriver(DrvServiceName);
	}
	
	PRINT("[*] After loading/unloading the driver...\n");
	if (!NT_SUCCESS(status)) {
		if (status == 0xc000010e)
			PRINT("[!] ALREADY LOADED!\n");
		else {
			PRINT("[-] FAILED! (%x)\n", status);
			ret = FALSE;
		}
	} else
		PRINT("[+] DONE!\n\n");
	
	return ret;
}

BOOL LoadDriver(WCHAR *ServiceName) {
	return LoadUnloadDriver(TRUE,ServiceName);
}

BOOL UnLoadDriver(WCHAR *ServiceName) {
	return LoadUnloadDriver(FALSE,ServiceName);
}


